\begin{ex}%[9H5V2-5]
Cho tam giác ${ABC}$ cân tại ${A}$. Vẽ ${(O)}$ đường kính ${BC}$. Đường tròn này cắt ${AB}$; ${AC}$ lần lượt tại ${I}$; ${K}$. Biết ${\widehat{BAC} }= 30^{\circ}$. Số đo ${\widehat {IOK}}$ là
\choice
{ $124^{\circ}$   }
   { $122^{\circ}$   }
     {  $118^{\circ}$  }
    { \True $120^{\circ}$  }
\loigiai{
Vì tam giác ${ABC}$ cân tại ${A}$ nên $\widehat{ABC}=\widehat{ACB} = \dfrac{180^{\circ} - \widehat{BAC} }{2} = 75^{\circ}$\\
Tam giác ${BOI}$ cân tại ${O}$ nên $\widehat{IBO}=\widehat{BIO}=75^{\circ}$ nên $\widehat{BIO}=180^{\circ} -2.75^{\circ}= 30^{\circ} $\\
Tương tự $\widehat{COK}=30^{\circ}$\\
$\widehat{IOK}=180^{\circ}-2.30^{\circ}=120^{\circ}$
}\end{ex}

